#include <stdio.h>

int main(void) {
    int n;
    while (scanf("%d", &n) == 1) {
        int count_d[61] = {0};
        int count_e[61] = {0};

        for (int i = 0; i < n; i++) {
            int m;
            char l;
            if (scanf("%d %c", &m, &l) == 2) {
                if (l == 'D') {
                    count_d[m]++;
                } else if (l == 'E') {
                    count_e[m]++;
                }
            }
        }

        int total_pairs = 0;
        for (int m = 30; m <= 60; m++) {
            total_pairs += (count_d[m] < count_e[m]) ? count_d[m] : count_e[m];
        }

        printf("%d\n", total_pairs);
    }

    return 0;
}
